function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 30000) return 'The tree has at most 30000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -30000 || v > 30000)) return 'Each node value is a whole number from -30000 to 30000.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  return null;
}

