function longestConsecutive(root) {
  let best = 0;

  // Returns [increasing, decreasing]: the longest downward runs that start at node.
  function dfs(node) {
    let increasing = 1;
    let decreasing = 1;
    for (const child of [node.left, node.right]) {
      if (child === null) {
        continue;
      }
      const [childIncreasing, childDecreasing] = dfs(child);
      if (child.val === node.val + 1) {
        increasing = Math.max(increasing, childIncreasing + 1);
      } else if (child.val === node.val - 1) {
        decreasing = Math.max(decreasing, childDecreasing + 1);
      }
    }
    best = Math.max(best, increasing + decreasing - 1);
    return [increasing, decreasing];
  }

  dfs(root);
  return best;
}

