function longestConsecutive(root) {
  // Treat the tree as an undirected graph. Read from its smaller end, every consecutive path rises by one
  // per step, so try every start node and keep stepping to a neighbour whose value is one larger.
  const neighbours = new Map([[root, []]]);
  const all = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    all.push(node);
    for (const child of [node.left, node.right]) {
      if (!child) continue;
      neighbours.set(child, [node]);
      neighbours.get(node).push(child);
      stack.push(child);
    }
  }
  const rise = node => {
    let longest = 1;
    for (const next of neighbours.get(node)) if (next.val === node.val + 1) longest = Math.max(longest, 1 + rise(next));
    return longest;
  };
  let best = 0;
  for (const node of all) best = Math.max(best, rise(node));
  return best;
}

